use crate::wasi::clocks::wall_clock;

struct Node;

/// Days from 1970-01-01 to 9999-12-31 inclusive of the lower bound.
/// Clamping here keeps the year within four digits so the date is always 10 chars.
const MAX_DAYS: u64 = 2_932_896;

/// Converts days since 1970-01-01 to (year, month, day) using the
/// proleptic Gregorian calendar (Howard Hinnant's civil_from_days).
fn civil_from_days(days: u64) -> (u64, u32, u32) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let days = (started / 86_400).min(MAX_DAYS);
        let (y, m, d) = civil_from_days(days);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

export!(Node);
